//  อัดคลิปโน้ตเป็นไฟล์ .mp4 — ตัวทำงานจริงของฟีเจอร์ (ไม่ใช่ตัววัด)
//
//  ★ ที่มา: ยกออกมาจาก `raster_bench.ts` ซึ่งเป็นเครื่องมือวัด · ตัววัดยังอยู่
//    และยังเรียกชิ้นส่วนชุดเดียวกันนี้ได้ — **กฎเดิม: ของจริงกับตัวตรวจต้องเดินทางเดียวกัน**
//
//  ทางเดินทั้งเส้น (พิสูจน์ในแอปจริงแล้ว ดู .scratch/thaiscore-mac/PLAN.md ข้อ 7–15):
//    ๑ ฝังฟอนต์ + CSS ของหน้าเป็น data URI (ครั้งเดียวต่อคลิป)
//    ๒ เรนเดอร์เสียงทั้งเพลงทีเดียวด้วย OfflineAudioContext → ส่งให้ฝั่ง Rust
//    ๓ วาดทีละเฟรมลงผืนวาด แล้วส่ง **พิกเซลดิบ** เข้าคิวของตัวเข้ารหัส
//    ๔ ปิดไฟล์ แล้วรวมภาพกับเสียงเป็น mp4 ใบเดียว
//
//  ★★ ความยาวคลิปยึดตาม **เสียงที่เรนเดอร์เสร็จแล้ว** ★★ ไม่คำนวณเอง —
//    ตัวเรนเดอร์เสียงเผื่อหางเสียงท้ายเพลงไว้แล้ว ถ้าวิดีโอสั้นกว่า เสียงจะถูกตัด
//  ★★ ภาพกับเสียงตรงกันโดยไม่ต้อง sync ★★ ทั้งสองฝั่งคิดจาก `secPerTick` ตัวเดียวกัน
// ════════════════════════════════════════════════════════════════════
import { invoke } from '@tauri-apps/api/core';
import * as L from './clip_layouts';
import { decode, embedFontCss, pageCss, rootVars, svgDirect, svgFor, toDrawable } from './clip_raster';
import { renderClipAudio, wavBytes } from './clip_audio';

/** ★ ยกมาจาก clip_layouts เพื่อให้หน้าจอ import ที่เดียว (กล่องเลือกแบบใช้ตัวนี้) */
export const CLIP_LAYOUTS = L.LAYOUTS;
export const CLIP_SIZES = L.SIZES;

export type ClipStep = 'prep' | 'audio' | 'frames' | 'finish';
export type ClipProgress = { step: ClipStep; done: number; total: number };

/** ★ ผู้ใช้กดยกเลิกกลางคัน — ไม่ใช่ความผิดพลาด หน้าจอต้องไม่ขึ้นกล่องแดง */
export const CLIP_CANCELLED = 'คลิป:ยกเลิก';

/** ★★ เพดานจำนวนภาพชิ้นที่เก็บไว้ ★★ เพลงยาว ๆ (สาธุการ 432 ห้อง) มีหน้า/ช่วง
 *  หลายสิบชิ้น ชิ้นละหลายล้านพิกเซล — เก็บทุกชิ้นคือกินหน่วยความจำไม่มีเพดาน
 *  หนึ่งเฟรมใช้ไม่กี่ชิ้น เก็บ 12 ชิ้นล่าสุดจึงพอและไม่ต้องวาดซ้ำเวลาเลื่อนกลับ */
const TILE_CAP = 12;

export type ClipArgs = {
  song: any;
  pack: any;
  bank: any;
  /** กระดาษไทยที่อยู่บนจอจริง (`.tn-sheet`) — ตำแหน่งห้อง/ช่องอ่านจากตัวนี้ */
  paper: HTMLElement;
  /** แบบคลิป · ดู CLIP_LAYOUTS */
  layout: string;
  /** แนวภาพ · ดู CLIP_SIZES */
  size: string;
  chingOn?: boolean;
  fps?: number;
  /** ตัดคลิปให้สั้นกว่าเพลงจริง (วินาที) — ใช้ทำตัวอย่างสั้น ๆ จากเพลงยาว
   *  ★ เสียงยังเรนเดอร์ทั้งเพลงตามเดิม แล้วถูกตัดตามความยาวภาพตอนรวมไฟล์ */
  maxSeconds?: number;
  onProgress?: (p: ClipProgress) => void;
  /** คืน true เมื่อผู้ใช้กดยกเลิก — ถูกถามทุกเฟรม */
  cancelled?: () => boolean;
};

export type ClipResult = {
  /** ที่อยู่ไฟล์ชั่วคราวของระบบ — หน้าจอต้องเรียก `clip_save` เพื่อเก็บที่ผู้ใช้เลือก */
  path: string;
  bytes: number;
  frames: number;
  seconds: number;
  ms: number;
};

export async function makeClip(o: ClipArgs): Promise<ClipResult> {
  const t0 = performance.now();
  const fps = o.fps || 30;
  const size = CLIP_SIZES.find((s) => s.tag === o.size) || CLIP_SIZES[0];
  const lay = CLIP_LAYOUTS.find((x) => x.tag === o.layout) || CLIP_LAYOUTS[0];
  const wantWestern = lay.tag.startsWith('west');
  const step = (s: ClipStep, done: number, total: number) => o.onProgress?.({ step: s, done, total });
  const stop = () => { if (o.cancelled?.()) throw new Error(CLIP_CANCELLED); };

  const spt = (60 / (Number(o.song.bpm) || 65)) / (Number(o.song.ticksPerHong) || 480);
  const tph = Number(o.song.ticksPerHong) || 480;
  const slotTicks = tph / 4;

  // ── ๑ เตรียมฟอนต์ + CSS + ภาพต้นฉบับ ───────────────────────────
  step('prep', 0, 3);
  const font = await embedFontCss();
  const css = `${font.css}\n${pageCss()}`;
  const vars = rootVars();
  stop();

  const box = o.paper.getBoundingClientRect();
  step('prep', 1, 3);
  const cached = await toDrawable(
    await decode(svgFor(o.paper, { w: box.width, h: box.height }, { w: box.width, h: box.height }, css, vars)),
    box.width, box.height,
  );
  const sheet: any = { img: cached, w: box.width, h: box.height, ...L.readSheet(o.paper) };
  stop();

  // ★ แผ่นสากล = หลาย <svg> ใบ ใบละหนึ่งบรรทัด · เตรียมเฉพาะตอนคลิปเป็นแบบสากล
  const wnEls = wantWestern ? [...document.querySelectorAll('.wn-host svg')] as SVGElement[] : [];
  if (wantWestern && !wnEls.length) {
    throw new Error(CLIP_NO_WESTERN);
  }
  const systems = [];
  for (const el of wnEls) {
    const d = svgDirect(el, css, vars);
    systems.push({
      img: await toDrawable(await decode(d.svg), d.w, d.h), w: d.w, h: d.h, ...L.readWesternSystem(el),
    });
    stop();
  }
  const western: any = systems.length ? { systems } : undefined;
  step('prep', 3, 3);

  // ── ๒ เสียงทั้งเพลงทีเดียว ─────────────────────────────────────
  step('audio', 0, 1);
  const a = await renderClipAudio(o.song, o.pack, o.bank, spt, { chingOn: o.chingOn !== false });
  await invoke('clip_audio', wavBytes(a.buffer).slice());
  step('audio', 1, 1);
  stop();

  // ★ ความยาวภาพ = ความยาวเสียงที่เรนเดอร์ได้จริง (รวมหางเสียงท้ายเพลงแล้ว)
  const seconds = Math.max(1, Math.min(a.buffer.duration, o.maxSeconds || Infinity));
  const total = Math.max(1, Math.round(seconds * fps));

  const title = String(o.song.title || 'ไม่ตั้งชื่อ');
  const rates = [...new Set((o.song.sections || []).map((x: any) => x.rate).filter(Boolean))];
  const subtitle = [o.song.instrumentTh, rates.join(' · ')].filter(Boolean).join(' · ');

  const cv = document.createElement('canvas');
  cv.width = size.w; cv.height = size.h;
  const ctx = cv.getContext('2d', { willReadFrequently: true })!;

  // ── ๓ วาดทีละเฟรม แล้วส่งเข้าคิวของตัวเข้ารหัส ──────────────────
  await invoke('clip_begin', { width: size.w, height: size.h, fps });
  const tiles = new Map<string, CanvasImageSource>();
  let lastStamp = '';
  try {
    for (let f = 0; f < total; f += 1) {
      if (o.cancelled?.()) { await invoke('clip_abort').catch(() => {}); throw new Error(CLIP_CANCELLED); }
      const tick = (f / fps) / spt;
      const base = {
        ctx, W: size.w, H: size.h, sheet, western, title, subtitle,
        hongNo: Math.floor(tick / tph),
        slotTick: Math.floor(tick / slotTicks) * slotTicks,
        tiles,
      };
      // ★ คิดแผนใหม่เฉพาะตอนช่องเวลาเปลี่ยน — `planFor` ต้องให้ตัววาดเดินจริงหนึ่งรอบ
      //   ถ้าทำทุกเฟรมเท่ากับวาดสองเท่าโดยเปล่าประโยชน์
      const stamp = `${base.hongNo}.${base.slotTick}`;
      const need = stamp === lastStamp ? [] : L.planFor(lay.draw, base);
      for (const t of need) {
        if (tiles.has(t.key)) continue;
        const out = { w: Math.round(t.dst.w), h: Math.round(t.dst.h) };
        const svg = t.kind === 'thai'
          ? svgFor(o.paper, { w: box.width, h: box.height }, out, css, vars, t.crop)
          : svgDirect(wnEls[t.sys!], css, vars, out.w).svg;
        tiles.set(t.key, await toDrawable(await decode(svg), out.w, out.h));
      }
      trimTiles(tiles, need.map((t) => t.key));
      lastStamp = stamp;

      lay.draw(base);
      const px = new Uint8Array(ctx.getImageData(0, 0, size.w, size.h).data.buffer);
      await invoke('clip_frame', px);
      if (f % fps === 0 || f === total - 1) step('frames', f + 1, total);
    }
  } catch (e) {
    // ★ ล้มกลางคันต้องเก็บกวาดเสมอ ไม่งั้นคลิปถัดไปเจอ "มีคลิปที่ยังอัดไม่จบค้างอยู่"
    await invoke('clip_abort').catch(() => {});
    closeTiles(tiles); (cached as ImageBitmap).close?.();
    throw e;
  }

  // ── ๔ ปิดไฟล์ แล้วรวมภาพกับเสียง ───────────────────────────────
  step('finish', 0, 1);
  const done = await invoke<{ frames: number }>('clip_end');
  const out = await invoke<{ path: string; bytes: number }>('clip_mux');
  closeTiles(tiles); (cached as ImageBitmap).close?.();
  step('finish', 1, 1);
  return { path: out.path, bytes: out.bytes, frames: done.frames, seconds, ms: performance.now() - t0 };
}

/** เพลงนี้ยังไม่มีแผ่นสากลบนจอ — ต้องบอกให้ผู้ใช้เปิดมุมมองสากลก่อน ไม่ใช่เงียบ */
export const CLIP_NO_WESTERN = 'คลิป:ไม่มีแผ่นสากลบนจอ';

/** เก็บภาพชิ้นไว้แค่เท่าที่จำเป็น — ★ ห้ามทิ้งชิ้นที่เฟรมนี้กำลังใช้ */
function trimTiles(tiles: Map<string, CanvasImageSource>, keep: string[]) {
  if (tiles.size <= TILE_CAP) return;
  for (const k of [...tiles.keys()]) {
    if (tiles.size <= TILE_CAP) break;
    if (keep.includes(k)) continue;
    (tiles.get(k) as ImageBitmap)?.close?.();
    tiles.delete(k);
  }
}

function closeTiles(tiles: Map<string, CanvasImageSource>) {
  for (const v of tiles.values()) (v as ImageBitmap)?.close?.();
  tiles.clear();
}
